function generateLgsFiles() {
  let count = 0;
  for (const [subject, diffs] of Object.entries(lgsData)) {
    for (const [diff, questionsList] of Object.entries(diffs)) {
      const dirPath = path.join(baseDir, subject);
      if (!fs.existsSync(dirPath)) {
        fs.mkdirSync(dirPath, { recursive: true });
      }

      const defaultDurationMs = diff === 'EASY' ? 15000 : diff === 'HARD' ? 25000 : 20000;
      const prefix = `LGS-${subject.slice(0, 3).toUpperCase()}-${diff[0]}`;

      const questions = questionsList.map((item, idx) => ({
        externalId: `${prefix}-${String(idx + 1).padStart(3, '0')}`,
        subTopic: item.subTopic,
        text: formatQuestionText(item.text),
        explanation: formatQuestionText(item.explanation),
        imageUrl: null,
        options: item.options.map((opt) => formatQuestionText(opt)),
        correctOptionIndex: item.correctOptionIndex,
      }));

      const payload = {
        meta: {
          examType: 'LGS',
          subject,
          difficulty: diff,
          defaultDurationMs,
        },
        questions,
      };

      const targetFile = path.join(dirPath, `${diff.toLowerCase()}.json`);
      fs.writeFileSync(targetFile, JSON.stringify(payload, null, 2), 'utf8');
      count += questions.length;
    }
  }

  console.log(`LGS klasörü başarıyla oluşturuldu: 7 ders/alan x 3 zorluk = 21 dosya, toplam ${count} LGS sorusu eklendi.`);
}

generateLgsFiles();
